import{z as A,x as d,o as l,c as p,q as E,j as n,D as t,d as r,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"校准周期","description":"","frontmatter":{"title":"校准周期","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/scanner-calibration-cycle.md","filePath":"litho/scanner-calibration-cycle.md","lastUpdated":1791063341000}'),B={name:"litho/scanner-calibration-cycle.md"};function c(m,a,h,u,f,C){const i=d("Mermaid");return l(),p("div",null,[a[2]||(a[2]=E('<h1 id="校准周期" tabindex="-1">校准周期 <a class="header-anchor" href="#校准周期" aria-label="Permalink to &quot;校准周期&quot;">​</a></h1><div class="epigraph"><p>校准把剂量、焦点、网格和照明瞳拉回机台自己的零。周期太疏，指纹爬出预算；太密，稼动被校准吃掉。</p><footer>—— 对照 scanner calibration / baseline；[机台匹配](/litho/tool-matching)</footer></div><p><a href="/litho/tool-recipe-software">上一课</a>保证执行的是那张配方。缺口是硬件零点会漂：灯、镜头、尺、空气。本课钉校准周期，曝光机单元收到这里；EUV 源从下一课程另起。配方管执行对不对，校准管零点在不在，两层错会互相掩护。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>激光老化改剂量；热改网格；污染改瞳。在线传感器能追一部分，不能替代离线基准。只做匹配不做单机校准，两台会一起慢慢歪。</p><p><span class="marginnote">术语翻译：校准是把单台机器的零点调回「它自己该在的位置」；匹配是把两台机器的零点调到「彼此一致」。先有各自的准，才谈得上互相像。</span></p><p>展开：漂移源各有时间常数——激光老化改剂量，天到周；热与蠕变改网格与正交，随环境与产量走；污染改瞳，最慢也最隐蔽。在线传感器（机内剂量、焦面）追得上快漂，但自身没有绝对基准，要靠低频离线校准喂参考。只做匹配不做单机校准的陷阱：两台一起歪时机差看着不变，绝对偏移却在爬——匹配掩盖整体漂移。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层：班次快速检查（剂量、焦点）、日/周网格与照明、月度像差或换件后全套。触发：超 SPC、换激光、动镜头后强制。时间进稼动的计划停，不要和故障混报。与轨道热板校准分开记账。</p><p>工程流程：账本分三层——班次/日做剂量与焦点快检，用在线传感器加短循环监控片；周做网格、正交与照明均匀性；月或事件后做全套，含像差与瞳。触发式插单校准接在 SPC 报警后：超限即补针对性校准，不等整周期。时间记账与稼动课对齐：别把校准藏进生产时间，报表失真则周期权衡没法算。</p><p><span class="marginnote">直觉类比：按漂移速率分配校准周期，像家务分级——碗（剂量/焦点）每顿洗，地板（网格/照明）每周拖，窗帘（像差/瞳）每季拆一次。全按季度做，碗会臭；全按顿做，人被家务吃掉。</span></p>',11)),(l(),n(s,null,{default:t(()=>[o(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DRIFT%5B%22%E7%81%AF%20%2F%20%E7%83%AD%20%2F%20%E6%B1%A1%E6%9F%93%22%5D%20--%3E%20CAL%5B%22%E6%A0%A1%E5%87%86%22%5D%0A%20%20CAL%20--%3E%20ZERO%5B%22%E5%8D%95%E6%9C%BA%E9%9B%B6%E7%82%B9%22%5D%0A%20%20ZERO%20--%3E%20MATCH%5B%22%E5%86%8D%E8%B0%88%E5%8C%B9%E9%85%8D%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"校准不是越勤越好：每次校准都把「偏差测量加测量噪声」写进表，周期短于噪声水平时，校准在制造套刻散布。周期下限由测量噪声与漂移速率之比决定。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"校准片或机内传感器给出偏差，写入校正表。若校准片本身有指纹，会把片指纹写进所有产品。标准片要计量溯源。",-1)),a[6]||(a[6]=e("p",null,"写透一点：校准链是「基准 → 偏差测量 → 校正表 → 执行引用」。链上每一环都可能写进假零点：校准片自身有指纹（胶厚、图形密度不均）就把片指纹写进所有产品，所以标准片要计量溯源并定期外校。多套零点还会互相拉扯：剂量用机内传感器、套刻用片上基准，周期不同步时一格把网格拉向东、另一格按片场拉回西，零点缓慢摆动。分层的本质是按漂移速率分配机时：快漂配短周期，慢漂配长周期，单一周期要么浪费机时、要么放走漂移。",-1)),(l(),n(s,null,{default:t(()=>[o(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20REF%5B%22%E5%9F%BA%E5%87%86%3A%20%E6%BA%AF%E6%BA%90%E6%A0%87%E5%87%86%E7%89%87%22%5D%20--%3E%20MEAS%5B%22%E5%81%8F%E5%B7%AE%E6%B5%8B%E9%87%8F%22%5D%0A%20%20MEAS%20--%3E%20TAB%5B%22%E5%86%99%E6%A0%A1%E6%AD%A3%E8%A1%A8%22%5D%0A%20%20TAB%20--%3E%20EXEC%5B%22%E6%89%A7%E8%A1%8C%E5%BC%95%E7%94%A8%22%5D%0A%20%20B1%5B%22%E6%A0%87%E5%87%86%E7%89%87%E8%87%AA%E8%BA%AB%E6%9C%89%E6%8C%87%E7%BA%B9%22%5D%20-.-%3E%20REF%0A%20%20B2%5B%22%E5%9C%A8%E7%BA%BF%E4%BC%A0%E6%84%9F%E5%99%A8%E8%87%AA%E6%BC%82%22%5D%20-.-%3E%20MEAS%0A%20%20B3%5B%22%E5%A4%9A%E5%A5%97%E9%9B%B6%E7%82%B9%E4%BA%92%E7%9B%B8%E6%8B%89%E6%89%AF%22%5D%20-.-%3E%20TAB%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 EUV 源与真空侧的零点，也不写掩模厂的版检测量；校准只保「回到自己」，不保两机一致——机差归匹配课。在线传感器自身漂移时，校准链的输入先坏：传感器要随标准件复验，否则校准越准越错。</p><p><span class="marginnote">常见误区：以为在线传感器读数稳定就等于机器没漂。传感器自己也会漂——它只保证「前后可比」，不保证「绝对正确」；绝对基准必须定期由外部标准件喂给它。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>校准维护单机零点；匹配维护机差。</li><li>周期是预算与稼动的折中，要按漂移源分层。</li><li>本单元收束：下一课程从 EUV 起，源与真空另起一套零点。</li><li>出处：剂量焦点课；SEMI 校准通识。</li></ul>',5))])}const b=A(B,[["render",c]]);export{_ as __pageData,b as default};
